/* From Uiverse.io by Na3ar-17  - Tags: simple, action, button, hover button */
.__UIV_SCOPE__ .container {
  .__UIV_SCOPE__ * {
    outline: none;
    border: none;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: Arial, Helvetica, sans-serif;
  }
}

.__UIV_SCOPE__ .button {
  width: 140px;
  height: 32px;
  border-radius: 0.375rem;
  cursor: pointer;
  margin-top: 1rem;
  background-image: linear-gradient(#268bff, hsl(252, 82%, 57%));
  transition: all 0.3s ease;
  color: #fff;
  font-weight: 600;
}

.__UIV_SCOPE__ .button:hover {
  -webkit-animation: pulse 2s infinite;
  animation: pulse512 1.5s infinite;
  letter-spacing: 2px;
}

.__UIV_SCOPE__ .button:active {
  transform: translateY(4px);
}

@keyframes pulse512 {
  0% {
    box-shadow: 0 0 0 0 rgba(5, 186, 218, 0.4);
  }
  70% {
    box-shadow: 0 0 0 10px rgba(218, 103, 68, 0%);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(218, 103, 68, 0%);
  }
}
